class PilaVacia extends RuntimeException {
    PilaVacia(String m) { super(m); }
}
class Pila {
    private int n = 0;
    void push() { n++; }
    void pop() {
        if (n == 0) throw new PilaVacia("vacia");
        n--;
    }
}
public class Main {
    public static void main(String[] args) {
        Pila p = new Pila();
        p.push();
        try {
            p.pop();
            p.pop();
            System.out.println("fin");
        } catch (PilaVacia e) {
            System.out.println("error " + e.getMessage());
        }
    }
}

